import { prisma } from '@/lib/prisma'

export interface MemoCreateInput {
  title: string
  content: string
  category?: string | null
}

export interface MemoUpdateInput {
  title?: string
  content?: string
  category?: string | null
}

export function listMemos(userId: string, category?: string) {
  return prisma.memo.findMany({
    where: {
      userId,
      ...(category ? { category } : {}),
    },
    orderBy: { updatedAt: 'desc' },
  })
}

// 소유자 조건을 함께 걸어 타인 메모의 존재 여부를 404로 처리한다.
export function getMemo(userId: string, id: string) {
  return prisma.memo.findFirst({ where: { id, userId } })
}

export function createMemo(userId: string, data: MemoCreateInput) {
  return prisma.memo.create({
    data: {
      userId,
      title: data.title,
      content: data.content,
      category: data.category ?? null,
    },
  })
}

export async function updateMemo(userId: string, id: string, data: MemoUpdateInput) {
  const memo = await getMemo(userId, id)
  if (!memo) return null
  return prisma.memo.update({
    where: { id: memo.id },
    data: {
      ...(data.title !== undefined ? { title: data.title } : {}),
      ...(data.content !== undefined ? { content: data.content } : {}),
      ...(data.category !== undefined ? { category: data.category } : {}),
    },
  })
}

export async function deleteMemo(userId: string, id: string) {
  const memo = await getMemo(userId, id)
  if (!memo) return false
  await prisma.memo.delete({ where: { id: memo.id } })
  return true
}

import { Request, Response, NextFunction, Router } from 'express'
import { z } from 'zod'
import { requireAuth } from '@/middleware/auth'
import {
  listMemos,
  getMemo,
  createMemo,
  updateMemo,
  deleteMemo,
} from '@/services/memo'

const router = Router()

const memoBodySchema = z.object({
  title: z.string().min(1, '제목을 입력하세요.').max(200, '제목은 200자 이하로 입력하세요.'),
  content: z.string().max(100_000, '내용은 100,000자 이하로 입력하세요.').default(''),
  category: z.string().max(50, '카테고리는 50자 이하로 입력하세요.').nullish(),
})

const updateMemoSchema = memoBodySchema
  .partial()
  .refine((data) => Object.keys(data).length > 0, { message: '수정할 항목을 입력하세요.' })

const listQuerySchema = z.object({
  category: z.string().max(50, '카테고리는 50자 이하로 입력하세요.').optional(),
})

type AsyncHandler = (req: Request, res: Response, _next: NextFunction) => Promise<void>

function asyncRoute(handler: AsyncHandler) {
  return (req: Request, res: Response, next: NextFunction) => {
    handler(req, res, next).catch(next)
  }
}

router.use(requireAuth)

router.get(
  '/',
  asyncRoute(async (req, res) => {
    const parsed = listQuerySchema.safeParse(req.query)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }
    const memos = await listMemos(req.user!.id, parsed.data.category)
    res.json({ memos })
  }),
)

router.get(
  '/:id',
  asyncRoute(async (req, res) => {
    const memo = await getMemo(req.user!.id, req.params.id)
    if (!memo) {
      res.status(404).json({ error: '메모를 찾을 수 없습니다.' })
      return
    }
    res.json({ memo })
  }),
)

router.post(
  '/',
  asyncRoute(async (req, res) => {
    const parsed = memoBodySchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }
    const memo = await createMemo(req.user!.id, parsed.data)
    res.status(201).json({ memo })
  }),
)

router.put(
  '/:id',
  asyncRoute(async (req, res) => {
    const parsed = updateMemoSchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }
    const memo = await updateMemo(req.user!.id, req.params.id, parsed.data)
    if (!memo) {
      res.status(404).json({ error: '메모를 찾을 수 없습니다.' })
      return
    }
    res.json({ memo })
  }),
)

router.delete(
  '/:id',
  asyncRoute(async (req, res) => {
    const deleted = await deleteMemo(req.user!.id, req.params.id)
    if (!deleted) {
      res.status(404).json({ error: '메모를 찾을 수 없습니다.' })
      return
    }
    res.json({ ok: true })
  }),
)

export default router

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import api from '@/lib/axios'
import type { Memo, MemoInput } from '@/types/schemas'

export function useMemos(category?: string) {
  return useQuery({
    queryKey: ['memos', category ?? ''],
    queryFn: async () => {
      const { data } = await api.get<{ memos: Memo[] }>('/memos', {
        params: category ? { category } : {},
      })
      return data.memos
    },
  })
}

export function useMemo(id: string | undefined) {
  return useQuery({
    queryKey: ['memos', 'detail', id],
    queryFn: async () => {
      const { data } = await api.get<{ memo: Memo }>(`/memos/${id}`)
      return data.memo
    },
    enabled: Boolean(id),
  })
}

export function useCreateMemo() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (input: MemoInput) => {
      const { data } = await api.post<{ memo: Memo }>('/memos', input)
      return data.memo
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['memos'] })
    },
  })
}

export function useUpdateMemo() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ id, ...input }: MemoInput & { id: string }) => {
      const { data } = await api.put<{ memo: Memo }>(`/memos/${id}`, input)
      return data.memo
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['memos'] })
    },
  })
}

export function useDeleteMemo() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (id: string) => {
      const { data } = await api.delete<{ ok: boolean }>(`/memos/${id}`)
      return data.ok
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['memos'] })
    },
  })
}

import { useMemo, useState } from 'react'
import MDEditor from '@uiw/react-md-editor'
import {
  useMemos,
  useMemo as useMemoDetail,
  useCreateMemo,
  useUpdateMemo,
  useDeleteMemo,
} from '@/api/memos'
import { memoInputSchema, type Memo, type MemoInput } from '@/types/schemas'

type EditorMode = 'create' | 'edit' | null

export default function Memos() {
  const [categoryFilter, setCategoryFilter] = useState('')
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [editorMode, setEditorMode] = useState<EditorMode>(null)
  const [form, setForm] = useState({ title: '', content: '', category: '' })
  const [formErrors, setFormErrors] = useState<Partial<Record<keyof MemoInput, string>>>({})

  // 카테고리 옵션은 필터와 무관하게 전체 목록에서 추출한다.
  const { data: allMemos } = useMemos()
  const { data: memos, isLoading } = useMemos(categoryFilter || undefined)
  const { data: selected } = useMemoDetail(editorMode ? undefined : (selectedId ?? undefined))
  const createMemo = useCreateMemo()
  const updateMemo = useUpdateMemo()
  const deleteMemo = useDeleteMemo()

  const categories = useMemo(
    () =>
      Array.from(
        new Set(
          (allMemos ?? [])
            .map((memo) => memo.category)
            .filter((category): category is string => Boolean(category)),
        ),
      ).sort(),
    [allMemos],
  )

  const startCreate = () => {
    setForm({ title: '', content: '', category: '' })
    setFormErrors({})
    setEditorMode('create')
    setSelectedId(null)
  }

  const startEdit = (memo: Memo) => {
    setForm({ title: memo.title, content: memo.content, category: memo.category ?? '' })
    setFormErrors({})
    setEditorMode('edit')
    setSelectedId(memo.id)
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    const input: MemoInput = {
      title: form.title,
      content: form.content,
      category: form.category.trim() ? form.category.trim() : undefined,
    }
    const parsed = memoInputSchema.safeParse(input)
    if (!parsed.success) {
      const fieldErrors: Partial<Record<keyof MemoInput, string>> = {}
      for (const issue of parsed.error.issues) {
        const key = issue.path[0] as keyof MemoInput
        if (!fieldErrors[key]) {
          fieldErrors[key] = issue.message
        }
      }
      setFormErrors(fieldErrors)
      return
    }
    setFormErrors({})
    if (editorMode === 'create') {
      createMemo.mutate(parsed.data, {
        onSuccess: (memo) => {
          setEditorMode(null)
          setSelectedId(memo.id)
        },
      })
    } else if (editorMode === 'edit' && selectedId) {
      updateMemo.mutate({ id: selectedId, ...parsed.data }, { onSuccess: () => setEditorMode(null) })
    }
  }

  const handleDelete = (id: string) => {
    if (!window.confirm('이 메모를 삭제할까요?')) return
    deleteMemo.mutate(id, {
      onSuccess: () => {
        if (selectedId === id) setSelectedId(null)
        if (editorMode === 'edit') setEditorMode(null)
      },
    })
  }

  const isSaving = createMemo.isPending || updateMemo.isPending

  return (
    <div className="min-h-screen bg-background p-8" data-color-mode="light">
      <div className="mx-auto max-w-5xl">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold text-foreground">메모</h1>
          <button
            onClick={startCreate}
            className="rounded bg-primary px-4 py-2 text-primary-foreground hover:bg-primary/90"
          >
            새 메모
          </button>
        </div>

        <div className="mt-4">
          <label htmlFor="category-filter" className="mr-2 text-sm font-medium text-foreground">
            카테고리
          </label>
          <select
            id="category-filter"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="rounded border border-input bg-background px-3 py-2 text-foreground"
          >
            <option value="">전체</option>
            {categories.map((category) => (
              <option key={category} value={category}>
                {category}
              </option>
            ))}
          </select>
        </div>

        <div className="mt-6 grid gap-6 md:grid-cols-[280px_1fr]">
          <section aria-label="메모 목록">
            {isLoading ? (
              <p className="text-muted-foreground">불러오는 중...</p>
            ) : !memos || memos.length === 0 ? (
              <p className="text-muted-foreground">메모가 없습니다.</p>
            ) : (
              <ul className="space-y-2">
                {memos.map((memo) => (
                  <li key={memo.id}>
                    <button
                      onClick={() => {
                        setSelectedId(memo.id)
                        setEditorMode(null)
                      }}
                      className={`w-full rounded border px-3 py-2 text-left ${
                        selectedId === memo.id
                          ? 'border-primary bg-accent'
                          : 'border-border bg-card hover:bg-accent'
                      }`}
                    >
                      <span className="block truncate font-medium text-card-foreground">
                        {memo.title}
                      </span>
                      {memo.category && (
                        <span className="mt-1 inline-block rounded bg-secondary px-2 py-0.5 text-xs text-secondary-foreground">
                          {memo.category}
                        </span>
                      )}
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </section>

          <section aria-label="메모 내용">
            {editorMode ? (
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label htmlFor="memo-title" className="block text-sm font-medium text-foreground">
                    제목
                  </label>
                  <input
                    id="memo-title"
                    value={form.title}
                    onChange={(e) => setForm((prev) => ({ ...prev, title: e.target.value }))}
                    className="mt-1 w-full rounded border border-input bg-background px-3 py-2 text-foreground"
                  />
                  {formErrors.title && (
                    <p className="mt-1 text-sm text-destructive">{formErrors.title}</p>
                  )}
                </div>
                <div>
                  <label
                    htmlFor="memo-category"
                    className="block text-sm font-medium text-foreground"
                  >
                    카테고리
                  </label>
                  <input
                    id="memo-category"
                    value={form.category}
                    onChange={(e) => setForm((prev) => ({ ...prev, category: e.target.value }))}
                    className="mt-1 w-full rounded border border-input bg-background px-3 py-2 text-foreground"
                  />
                  {formErrors.category && (
                    <p className="mt-1 text-sm text-destructive">{formErrors.category}</p>
                  )}
                </div>
                <div>
